import test from 'node:test';import assert from 'node:assert/strict';
import {TILE_EVENT_TYPES,EVENT_TYPES,EVENT_CATALOG,eventTypeForTile,bonusPath,openBoardEvent,resolveBoardEvent,chooseEventIntent} from './scenario-adventure/board-events.js';
import {createScenarioAdventureMatch} from './scenario-adventure/scenario-engine.js';
import {createDeckState,prepareDeckForTurn} from './scenario-adventure/deck-engine.js';
import {OnlineRooms} from './scenario-adventure/online-rooms.mjs';
const allowedIds=['patch-update','firewall-guard','energy-boost'],cards=[...allowedIds,'patch-update','firewall-guard'];const inventory={allowedIds},setup={characterId:'milo',cardIds:cards};
function context(){return {match:createScenarioAdventureMatch(),actorId:'player',deck:createDeckState(cards),allowedIds,position:0};}
test('32 real tile mapping and all five types including START; distributed counts',()=>{assert.equal(TILE_EVENT_TYPES.length,32);assert.deepEqual(EVENT_TYPES.map(t=>TILE_EVENT_TYPES.filter(x=>x===t).length),[12,6,5,5,4]);assert.equal(eventTypeForTile(0),'ACTION');for(let i=0;i<32;i++)assert.ok(EVENT_TYPES.includes(eventTypeForTile(i)));});
test('all 32 landings open once; only ACTION consumes shared scenario content',async()=>{for(let tileIndex=0;tileIndex<32;tileIndex++){const c=context(),o=await openBoardEvent({...c,tileIndex,random:()=>0});assert.equal(o.match.eventHistory.length,1);assert.equal(o.match.scenarioHistory.length,o.event.type==='ACTION'?1:0);await assert.rejects(openBoardEvent({...c,match:o.match,tileIndex}),/EVENT_ALREADY_OPENED/);}});
test('bonus +/-2 wraps in actual path, commits once without destination event',async()=>{assert.deepEqual(bonusPath(31,2),[0,1]);assert.deepEqual(bonusPath(0,-2),[31,30]);assert.throws(()=>bonusPath(0,3));for(const choiceId of ['forward','review']){const c=context(),o=await openBoardEvent({...c,tileIndex:1,random:()=>0});const r=resolveBoardEvent({...c,...o,intent:{choiceId}});assert.equal(r.match.turns.player,1);assert.equal(r.match.eventHistory.length,1);assert.equal(r.match.scenarioHistory.length,0);assert.equal(r.position,choiceId==='forward'?2:30);const duplicate=resolveBoardEvent({...c,...o,match:r.match,deck:r.deck,intent:{choiceId}});assert.equal(duplicate.duplicate,true);assert.equal(duplicate.match.turns.player,1);}});
test('explicit choices, meaningful risk, bounds, ownership, forged choice and wrong actor',async()=>{for(const type of ['SUPPORT','RISK','DECISION']){const c=context();c.match.scores.player={rp:0,stability:0};const o=await openBoardEvent({...c,tileIndex:2,type,random:()=>0});assert.throws(()=>resolveBoardEvent({...c,...o,intent:{choiceId:'fake'}}),/INVALID_EVENT_CHOICE/);assert.throws(()=>resolveBoardEvent({...c,...o,actorId:'bot',intent:{choiceId:o.event.choices[0].id}}));assert.throws(()=>resolveBoardEvent({...c,...o,intent:{responseType:'BASIC'}}),/EVENT_CHOICE_REQUIRED/);assert.throws(()=>resolveBoardEvent({...c,...o,intent:{choiceId:o.event.choices[0].id,rp:999,position:999}}),/INVALID_EVENT_INTENT/);const r=resolveBoardEvent({...c,...o,intent:{choiceId:o.event.choices[0].id}});assert.equal(r.match.turns.player,1);assert.ok(r.match.scores.player.rp<=2);assert.ok(r.match.scores.player.stability>=0);assert.equal(r.match.status,'PLAYING');}const c=context(),o=await openBoardEvent({...c,tileIndex:2,type:'SUPPORT',random:()=>0});assert.equal(resolveBoardEvent({...c,...o,intent:{choiceId:'restore'}}).match.scores.player.stability,10);});
test('RISK card still enforces allowed hand instance and repeated risk content can resolve later turn',async()=>{let c=context();for(let i=0;i<2;i++){const o=await openBoardEvent({...c,tileIndex:4,type:'RISK',random:()=>.9});assert.throws(()=>resolveBoardEvent({...c,...o,allowedIds:[],intent:{responseType:'CARD',instanceId:c.deck.hand[0].instanceId}}),/CARD_NOT_ALLOWED/);const r=resolveBoardEvent({...c,...o,intent:{responseType:'CARD',instanceId:c.deck.hand[0].instanceId}});c={...c,match:r.match,deck:prepareDeckForTurn(r.deck)};}assert.equal(c.match.turns.player,2);});
test('mixed pure resolver used by local path finishes six turns each; ACTION no repeat and no adjacent catalog text repeats',async()=>{let match=createScenarioAdventureMatch(),deck=createDeckState(cards),position=0,last=null;for(let i=0;i<12;i++){const actorId=i%2?'bot':'player';match={...match,currentTurn:actorId};const o=await openBoardEvent({match,actorId,tileIndex:i,random:()=>0});const intent=chooseEventIntent({...o,deck,allowedIds});const r=resolveBoardEvent({...o,actorId,deck,allowedIds,intent,position});assert.equal(r.duplicate,false);match=r.match;deck=prepareDeckForTurn(r.deck);position=r.position;if(o.event.type!=='ACTION')assert.notEqual(o.event.contentId,last);last=o.event.contentId;}assert.equal(match.status,'FINISHED');assert.equal(match.responseHistory.length,12);assert.equal(match.turns.player,6);assert.equal(match.turns.bot,6);assert.equal(new Set(match.scenarioHistory.map(e=>e.contentIdentity)).size,match.scenarioHistory.length);});
for(const count of [2,3,4])test(`authoritative ${count} seats mixed match, stale commands and replay`,async()=>{const users=Array.from({length:count},(_,i)=>({id:'mixed-'+i}));const service=new OnlineRooms({random:()=>0});const created=service.create(users[0],{...setup,maxPlayers:count},inventory),code=created.code;for(const u of users.slice(1))service.join(u,code,setup,inventory);const room=service.get(code,users[0].id);const act=(u,type,extra={})=>service.act(u,code,{revision:room.revision,type,...extra});for(const u of users)await act(u,'ready',{ready:true});await act(users[0],'start');assert.equal(room.event,null);for(let i=0;i<count*6;i++){const actor=room.match.currentTurn,u=users[room.match.actorOrder.indexOf(actor)];await act(u,'roll');const revision=room.revision;await act(u,'respond',chooseEventIntent({event:room.event,scenario:room.scenario,deck:room.decks[actor],allowedIds}));await assert.rejects(service.act(u,code,{revision,type:'respond',choiceId:'review'}),/STALE_REVISION/);if(room.status==='PLAYING')await act(u,'continue');}assert.equal(room.status,'FINISHED');assert.equal(room.match.eventHistory.length,count*6);for(const u of users)await act(u,'ready',{ready:true});await act(users[0],'start');assert.equal(room.match.eventHistory?.length||0,0);assert.equal(room.match.scenarioHistory.length,0);assert.equal(room.event,null);});
test('server bot uses mixed resolver to complete a four-seat match without client timers',async()=>{let now=1e6;const service=new OnlineRooms({random:()=>0,now:()=>now}),user={id:'bot-owner'},created=service.create(user,{...setup,maxPlayers:4,botCount:3},inventory),room=service.get(created.code,user.id);await service.act(user,room.code,{revision:room.revision,type:'ready',ready:true});await service.act(user,room.code,{revision:room.revision,type:'start'});for(let n=0;n<200&&room.status==='PLAYING';n++){const role=room.match.currentTurn;if(role!=='player'){now+=1e5;await service.tickBots();}else{const type=room.phase==='WAITING'?'roll':room.phase==='RESOLVED'?'continue':'respond';await service.act(user,room.code,{revision:room.revision,type,...(type==='respond'?chooseEventIntent({event:room.event,scenario:room.scenario,deck:room.decks.player,allowedIds}):{})});}}assert.equal(room.status,'FINISHED');assert.equal(room.match.responseHistory.length,24);});
